func (s *solver) solveCol(col int, carry int) bool {
    if col == s.numCols {
        return carry == 0
    }
    // gather letters in this column
    var addLetters []int // indices into s.letters
    for _, w := range s.addends {
        if len(w) > col {
            addLetters = append(addLetters, s.letterIdx[w[len(w)-1-col]])
        }
    }
    resLetter := -1
    if len(s.result) > col {
        resLetter = s.letterIdx[s.result[len(s.result)-1-col]]
    }
    // unassigned among addLetters
    var unassigned []int
    for _, li := range addLetters {
        if s.assign[li] < 0 { unassigned = append(unassigned, li) }
    }
    // enumerate
    var rec func(k int, sum int) bool
    rec = func(k, sum int) bool {
        if k == len(unassigned) {
            total := sum + carry
            if resLetter >= 0 {
                if s.assign[resLetter] >= 0 {
                    if s.assign[resLetter] != total%10 { return false }
                    return s.solveCol(col+1, total/10)
                }
                d := total % 10
                if s.used[d] { return false }
                if s.leading[resLetter] && d == 0 { return false }
                s.assign[resLetter] = d
                s.used[d] = true
                if s.solveCol(col+1, total/10) { return true }
                s.assign[resLetter] = -1
                s.used[d] = false
            } else {
                // no result letter in this column: total must be 0
                if total != 0 { return false }
                return s.solveCol(col+1, 0)
            }
