        li := unassigned[k]
        for d := 0; d <= 9; d++ {
            if s.used[d] { continue }
            if s.leading[li] && d == 0 { continue }
            s.assign[li] = d
            s.used[d] = true
            if rec(k+1, sum+d) { return true }
            s.assign[li] = -1
            s.used[d] = false
        }
        return false
    }
    return rec(0, 0)
}
