package alphametics

import (
	"errors"
	"strings"
)

// Solve solves an alphametics puzzle of the form
// "WORD1 + WORD2 + ... == RESULT" and returns the digit assigned to each
// letter, or an error if no solution exists.
func Solve(puzzle string) (map[string]int, error) {
	s := &solver{}
	if err := s.parse(puzzle); err != nil {
		return nil, err
	}
	if !s.solve(0, 0) {
		return nil, errors.New("no solution")
	}
	return s.solution(), nil
}

type solver struct {
	addends   []string
	result    string
	letterIdx map[rune]int
	assign    []int // digit per letter, -1 if unassigned
	leading   []bool
	used      [10]bool
	numCols   int
}

func (s *solver) parse(puzzle string) error {
	eq := strings.Split(puzzle, " == ")
	if len(eq) != 2 {
		return errors.New("invalid puzzle: expected exactly one '=='")
	}
	s.addends = strings.Split(eq[0], " + ")
	fields := strings.Fields(eq[1])
	if len(fields) != 1 {
		return errors.New("invalid puzzle: expected exactly one result word")
	}
	s.result = fields[0]

	words := append(append([]string{}, s.addends...), s.result)
	seen := map[rune]bool{}
	for _, w := range words {
		for _, r := range w {
			if !seen[r] {
				seen[r] = true
				s.letterIdx[r] = len(s.assign)
				s.assign = append(s.assign, -1)
				s.leading = append(s.leading, false)
			}
		}
	}
	if len(s.assign) > 10 {
		return errors.New("too many distinct letters")
	}
	for _, w := range words {
		if len(w) > 1 {
			s.leading[s.letterIdx[rune(w[0])]] = true
		}
	}
	s.numCols = len(s.result)
	for _, w := range s.addends {
		if len(w) > s.numCols {
			s.numCols = len(w)
		}
	}
	return nil
}
```

